### PricingCard.tsx
```tsx
import React, { useState } from 'react';

interface Feature {
  text: string;
}

interface PricingCardProps {
  planName: string;
  priceMonthly: number;
  priceYearly: number;
  features: Feature[];
}

const PricingCard: React.FC<PricingCardProps> = ({
  planName,
  priceMonthly,
  priceYearly,
  features,
}) => {
  const [isYearly, setIsYearly] = useState(false);

  const togglePlan = () => {
    setIsYearly(!isYearly);
  };

  const displayPrice = isYearly ? priceYearly : priceMonthly;

  return (
    <div className="max-w-md w-full bg-white rounded-lg shadow-md overflow-hidden border border-gray-100">
      <div className="p-6">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-semibold text-gray-800">{planName}</h2>
          <button
            onClick={togglePlan}
            className="text-sm font-medium text-gray-500 hover:text-gray-700 transition-colors"
          >
            {isYearly ? 'Monthly' : 'Yearly'}
          </button>
        </div>

        <div className="flex items-baseline mb-6">
          <span className="text-3xl font-bold text-gray-900">${displayPrice}</span>
          <span className="ml-1 text-lg text-gray-500">/mo</span>
        </div>

        <ul className="space-y-3 mb-6">
          {features.map((feature, index) => (
            <li key={index} className="flex items-center">
              <div className="h-5 w-5 flex-shrink-0 text-accent mr-3">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-full w-full"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <polyline points="20 6 9 17 4 12" />
                </svg>
              </div>
              <span className="text-gray-700">{feature.text}</span>
            </li>
          ))}
        </ul>

        <button className="w-full bg-accent text-white py-3 rounded-md font-semibold hover:bg-blue-600 transition-colors">
          Buy Now
        </button>
      </div>
    </div>
  );
};

const mockFeatures: Feature[] = [
  { text: 'Unlimited projects' },
  { text: 'Priority support' },
  { text: 'Advanced analytics' },
];

const mockData: PricingCardProps = {
  planName: 'Pro Plan',
  priceMonthly: 29,
  priceYearly: 299,
  features: mockFeatures,
};

export default PricingCard;
```
